            sheet = dict(watcher_char.sheet or {})
            hp = dict(sheet.get("hp") or {})
            hp_cur = int(hp.get("current") or 0)
            hp_max = int(hp.get("max") or 0)
            new_hp = min(hp_max, hp_cur + heal_back) if hp_max else hp_cur + heal_back
