def _pc_has_reliable_talent(
    sheet: "dict | None", stat_key: str,
) -> bool:
    """v2.99.197 — RAW Reliable Talent (Rogue Lv 11, PHB p.96):
    "Whenever you make an ability check that lets you add your
    proficiency bonus, you can treat a d20 roll of 9 or lower as a
    10."

    Returns True when:
      - PC's Rogue class level >= 11 (read via
        `_rogue_level_from_sheet`).
      - The `stat_key` resolves to a skill on the sheet's `skills`
        dict AND that skill is `proficient: True` (covers both
        proficient and expertise — expertise implies proficient).

    Gate is restrictive on purpose. Bare ability checks (str_check,
    wis_check) don't add proficiency by default, so they don't
    trigger Reliable Talent. Saves and attacks are routed through
    other paths and shouldn't trigger here either.

    Skill name lookup is case-insensitive; the sheet stores names
    as title-case ("Stealth"), the client sends title-case via
    `stat_key`, but the helper folds-case anyway for robustness.
    """
    if not sheet:
        return False
    if _rogue_level_from_sheet(sheet) < 11:
        return False
    stat_key_norm = (stat_key or "").strip()
    if not stat_key_norm:
        return False
    skills = sheet.get("skills") or {}
    if not isinstance(skills, dict):
        return False
    # Case-insensitive lookup.
    stat_key_lc = stat_key_norm.lower()
    for name, entry in skills.items():
        if not isinstance(entry, dict):
            continue
        if (str(name) or "").strip().lower() != stat_key_lc:
            continue
        return bool(entry.get("proficient") or entry.get("expertise"))
    return False


def _apply_reliable_talent_floor(
    result: "object", expr: str,
) -> "tuple[object, int | None, int | None]":
    """v2.99.197 — Floor the kept d20 of a roll at 10 (Reliable
    Talent). Returns `(new_result, old_d20, new_d20)` — old/new are
    None when the floor didn't apply (d20 already >= 10 or
    breakdown didn't parse).

    Mutates the breakdown string to swap the kept-d20 value (e.g.
    `1d20[6]=6 + 3 = 9` → `1d20[10]=10 + 3 = 13`) and adjusts the
    total by `(10 - old_d20)`. Construction-time intercepts (Rage
    advantage on STR checks) are honored because they shape the
    d20 expression BEFORE the roll, and this helper operates on
    the kept value AFTER all expansion.

    Returns the original result unchanged when the breakdown's kept
    d20 is already >= 10 or can't be parsed.
    """
    old_d20 = _extract_kept_d20_from_breakdown(
        getattr(result, "breakdown", "") or "",
    )
    if old_d20 is None or old_d20 >= 10:
        return result, None, None
    # Adjust the total.
    delta = 10 - old_d20
    try:
        new_total = int(getattr(result, "total", 0) or 0) + delta
    except (TypeError, ValueError):
        return result, None, None
    # Swap the breakdown's kept-d20 value. Replace ONLY the first
    # match — for advantage / disadvantage there may be a kl1/kh1
    # selection AND a per-die display; the kept-value match comes
    # first via the `\d*d20[^d=+ ]*=` regex.
    breakdown = getattr(result, "breakdown", "") or ""
    new_breakdown = _HALFLING_KEPT_D20_RE.sub(
        lambda m: m.group(0).replace(f"={old_d20}", "=10", 1),
        breakdown,
        count=1,
    )
    # Also update any trailing "= TOTAL" if present. The breakdown
    # convention is "1d20[6]=6 + 3 = 9"; the trailing "= 9" is the
    # running sum — rewrite it to "= NEW_TOTAL". Done via a simple
    # split-by-last-" = " + re-attach.
    if " = " in new_breakdown:
        parts = new_breakdown.rsplit(" = ", 1)
        try:
            int(parts[1])
            new_breakdown = f"{parts[0]} = {new_total}"
        except (TypeError, ValueError):
            pass
    # Construct a lightweight result clone. dice_mod's RollResult
    # is a dataclass-ish object — set attributes directly on a
    # shallow copy for compatibility with the existing call sites.
    try:
        import copy
        new_result = copy.copy(result)
        new_result.total = new_total
        new_result.breakdown = new_breakdown
    except Exception:
        return result, None, None
    return new_result, old_d20, 10


async def _broadcast_reliable_talent(
    campaign_id: int,
    char: "Character | None",
    old_d20: int,
    stat_key: str,
) -> None:
    """v2.99.197 — Companion broadcast for the Reliable Talent
    floor. Emits a `feature_used` event with
    `source: "reliable-talent"` so the chat-card surfaces the
    trigger ("Pip used 🎯 Reliable Talent — floored d20 6 → 10 on
    Stealth.").
    """
    if not char:
        return
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": char.color,
            "feature_name": (
                f"🎯 Reliable Talent — d20 {old_d20} → 10"
            ),
            "feature_desc": (
                f"{char.name} treated the d20 roll of {old_d20} as a "
                f"10 for "
                f"{stat_key or 'a proficient ability check'} "
                f"(Rogue Lv 11+ class feature)."
            ),
            "source": "reliable-talent",
            "stat_key": stat_key or "",
        },
    })


def _pc_has_halfling_lucky(sheet: "dict | None") -> bool:
    """Detect Halfling race trait Lucky on a PC sheet. Reads
    `sheet["race"]` slug via `_race_slug_from_sheet` and returns
    True when the normalized slug is "halfling" (covers Lightfoot
    Halfling, Stout Halfling, and the bare race string).

    Distinct from `_pc_has_lucky_available` (v2.77.0 Lucky feat),
    which gates on a 3-charge resource. Halfling Lucky is unlimited
    and triggers only on natural 1.
    """
    return _race_slug_from_sheet(sheet or {}) == "halfling"


import re as _re_lucky

# Matches "1d20[14]=14" / "2d20kh1[16,9]kh11=16" / "2d20kl1[8,3]kl11=3"
# — the kept value is the integer after the trailing `=`. Same shape
# as the v2.49.231 Improved Critical _D20_RE in
# tests/harness/test_use_attack_improved_critical.py.
_HALFLING_KEPT_D20_RE = _re_lucky.compile(
    r"\d*d20[^d=+ ]*=(\d+)", _re_lucky.IGNORECASE,
)


def _extract_kept_d20_from_breakdown(breakdown: str) -> "int | None":
    """Extract the kept d20 value from a dice breakdown string.
    Handles `1d20` (no adv/disadv), `2d20kh1` (advantage), and
    `2d20kl1` (disadvantage). Returns None when the breakdown
    doesn't contain a recognizable d20 component.

    Used by `_halfling_lucky_should_reroll` to decide whether
    Halfling Lucky's "rolled a 1" trigger fires.
    """
    if not breakdown:
        return None
    m = _HALFLING_KEPT_D20_RE.search(breakdown)
    if not m:
        return None
    try:
        return int(m.group(1))
    except (TypeError, ValueError):
        return None


# v2.99.17 — (D) Phase 3 second-ship: Half-Orc Relentless Endurance.
# RAW (PHB p.41): "When you are reduced to 0 hit points but not
# killed outright, you can drop to 1 hit point instead. You can't
# use this feature again until you finish a long rest."
#
# Implementation:
#   - Per-long-rest resource on the sheet (key="relentless-endurance",
#     current=1, max=1, reset="long"). Krieger gets one in the demo
#     seed; any future Half-Orc PC should as well.
#   - `_pc_has_relentless_endurance_available(sheet)` returns True
#     when the sheet has the resource AND current > 0. Doesn't
#     gate on race slug because the resource is the trait — if it's
#     on the sheet, the PC has it (the race normalization can be
#     re-added as a defense if it turns out homebrew abuses the
#     pattern).
#   - `_apply_hp_change` hook (v2.99.17): when damage drops the PC
#     from alive → 0 HP AND the massive-damage rule didn't fire
#     (not killed outright) AND the resource is available, clamp
#     new_current=1 + decrement the resource + stay alive. Returns
#     a `relentless_endurance_fired: True` flag in the result dict
#     so callers can broadcast the trigger.

def _pc_has_relentless_endurance_available(sheet: "dict | None") -> bool:
    """Detect Half-Orc Relentless Endurance availability on a PC
    sheet. Returns True when the sheet has the `relentless-endurance`
    resource with current > 0. The resource is the trait — the demo
    seed adds it for Krieger; future Half-Orc PCs should as well.
    """
    if not sheet:
        return False
    for r in (sheet.get("resources") or []):
        if not isinstance(r, dict):
            continue
        key = (r.get("key") or "").strip().lower()
        if key != "relentless-endurance":
            continue
        try:
            cur = int(r.get("current") or 0)
        except (TypeError, ValueError):
            cur = 0
        return cur > 0
    return False


def _decrement_relentless_endurance(sheet: dict) -> None:
    """In-place decrement of the relentless-endurance resource on
    a sheet. Called by `_apply_hp_change` after the HP clamp.
    """
    resources = list(sheet.get("resources") or [])
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "relentless-endurance":
            updated = dict(r)
            try:
                cur = int(updated.get("current") or 0)
            except (TypeError, ValueError):
                cur = 0
            updated["current"] = max(0, cur - 1)
            resources[i] = updated
            sheet["resources"] = resources
            return


async def _broadcast_relentless_endurance(
    campaign_id: int,
    char: "Character | None",
    damage_amount: int,
) -> None:
    """Companion broadcast for the Relentless Endurance auto-fire.
    Emits a `feature_used` event with `source: "relentless-endurance"`
    so the chat card surfaces the trigger ("Krieger used 💪 Relentless
    Endurance — dropped to 1 HP instead of 0 from 30 damage.").
    """
    if not char:
        return
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": char.color,
            "feature_name": "💪 Relentless Endurance — dropped to 1 HP",
            "feature_desc": (
                f"{char.name} took {damage_amount} damage but Relentless "
                f"Endurance (Half-Orc race trait) kept him alive at 1 HP. "
                f"1/long rest."
            ),
            "source": "relentless-endurance",
        },
    })


def _maybe_halfling_lucky_attack_reroll(
    char: "Character | None",
    atk_expr: str,
    result: "object",
) -> "tuple[object, int | None, int | None]":
    """v2.99.21 — attack-roll surface for Halfling Lucky.

    Inspects a freshly-rolled attack expression; if the kept d20 is
    1 AND the attacker is a Halfling, re-rolls the full expression
    once and returns the new RollResult. Returns
    `(new_result, old_d20, new_d20)` — old_d20 / new_d20 are None
    when no reroll fired so callers can short-circuit broadcasts.

    Mirrors the v2.99.13 save-roll surface (`/roll_request/respond`
    intercept) but lives in the synchronous /attack roll loop.
    `dice_mod.roll` raises `DiceParseError` on bad expressions; this
    helper guards that (callers shouldn't lose the original result
    just because the reroll itself fails).
    """
    if not char or not _pc_has_halfling_lucky(char.sheet):
        return result, None, None
    breakdown = getattr(result, "breakdown", "") or ""
    kept = _extract_kept_d20_from_breakdown(breakdown)
    if kept != 1:
        return result, None, None
    try:
        new_result = dice_mod.roll(atk_expr)
    except dice_mod.DiceParseError:
        return result, None, None
    new_kept = _extract_kept_d20_from_breakdown(new_result.breakdown or "")
    return new_result, 1, new_kept


