def _paladin_level_from_sheet(sheet: dict) -> int:
    """Read the paladin level out of a sheet (single-class or
    multiclass). Mirror of ``_barbarian_level_from_sheet`` /
    ``_monk_level_from_sheet`` / ``_rogue_level_from_sheet``. Used
    by ``_aura_of_protection_bonus`` to gate the Paladin Lv 6+
    ally-conferred save bonus.
    """
    if not sheet:
        return 0
    cls = (sheet.get("class") or "").strip().lower()
    if cls == "paladin":
        try:
            return int(sheet.get("level") or 0)
        except (TypeError, ValueError):
            return 0
    for entry in (sheet.get("classes") or []):
        if (entry.get("class") or "").strip().lower() == "paladin":
            try:
                return int(entry.get("level") or 0)
            except (TypeError, ValueError):
                return 0
    return 0


def _paladin_is_conscious(char: "Character | None") -> bool:
    """v2.66.0 — F1 follow-up. Paladin auras (AoP, AoD) require the
    paladin to be CONSCIOUS per RAW ("You must be conscious to grant
    this bonus"). Returns True when the paladin has hp > 0 AND
    death_saves.status indicates a conscious state.

    Conscious means hp > 0 and death_saves.status in
    {"alive", "stable"}. An unconscious paladin (hp == 0, status in
    {"dying", "dead"}) cannot emit the aura — RAW it suspends until
    they're back up.

    Used by ``_aura_of_protection_bonus`` and
    ``_ally_has_aura_of_devotion``. Sheet-driven so the check is
    free of init-tracker state — works whether the paladin is in
    battle or not.
    """
    if not char:
        return False
    sheet = char.sheet or {}
    hp = sheet.get("hp") or {}
    try:
        hp_current = int(hp.get("current") or 0)
    except (TypeError, ValueError):
        hp_current = 0
    if hp_current <= 0:
        return False
    ds = sheet.get("death_saves") or {}
    status = (ds.get("status") or "alive").strip().lower()
    return status in {"alive", "stable"}


def _aura_of_protection_bonus(
    db: Session, campaign_id: int, saving_char_id: int | None,
) -> "tuple[int, Character | None]":
    """v2.53.0 — Paladin Aura of Protection (Lv 6+). Returns
    ``(bonus, paladin_char)`` where bonus is the CHA modifier of
    the highest-CHA conscious paladin in the active battle's
    init tracker, and ``paladin_char`` is that paladin's Character
    row (so the caller can broadcast a feature_used event naming
    them). Returns ``(0, None)`` when no aura applies.

    RAW: "You and friendly creatures within 10 feet of you gain a
    bonus to all saving throws equal to your Charisma modifier
    (minimum bonus of +1). You must be conscious to grant this
    bonus." Paladin's own aura applies to themselves too.

    v1 simplifications:
      - **No 10 ft radius check** — any paladin in the same battle
        init grants the aura to every PC making a save. Same
        convention as Uncanny Dodge's "attacker that you can see"
        and Evasion's incapacitation gate. Filed: distance check
        via ``_distance_ft_between_points`` on map tokens, gated
        on the paladin being conscious.
      - **Multiple paladins don't stack** — if two paladins are in
        init, the higher CHA mod wins (RAW: auras don't stack).
        We pick the max, not the sum.
      - **Minimum +1** RAW: even if CHA mod is 0 or negative, the
        bonus is +1. Implemented via ``max(1, cha_mod)`` after the
        paladin gate fires.

    Saver-must-be-in-battle: if ``saving_char_id`` doesn't appear in
    the init tracker, the helper returns (0, None) — the aura is a
    battle-state mechanic, not a global "any paladin anywhere"
    effect.
    """
    if not saving_char_id:
        return 0, None
    state = hub.get_battle(campaign_id)
    if not state:
        return 0, None
    combatants = state.get("combatants") or []
    saver_in_battle = any(
        c.get("char_id") == saving_char_id for c in combatants
    )
    if not saver_in_battle:
        return 0, None
    best_bonus = 0
    best_paladin: "Character | None" = None
    for c in combatants:
        char_id = c.get("char_id")
        if not char_id:
            continue
        char = db.query(Character).filter(Character.id == int(char_id)).first()
        if not char:
            continue
        sheet = char.sheet or {}
        paladin_lv = _paladin_level_from_sheet(sheet)
        if paladin_lv < 6:
            continue
        # v2.66.0 — F1 follow-up. RAW: aura suspends when the paladin
        # is unconscious. Skip downed paladins so a dying Caelan
        # doesn't keep granting +CHA to saves.
        if not _paladin_is_conscious(char):
            continue
        # v2.61.0 — F1 range gate. Aura radius is 10 ft at Lv 6-17,
        # 30 ft at Lv 18+ per RAW. ``_distance_ft_between_chars``
        # returns None when token data is unavailable (no active map,
        # no grid, or either token off-map); we fall back to the
        # pre-v2.61.0 "any paladin in init" behavior in that case so
        # the aura still applies during off-grid narrative scenes.
        aura_radius_ft = 30.0 if paladin_lv >= 18 else 10.0
        distance_ft = _distance_ft_between_chars(
            db, campaign_id, int(char_id), int(saving_char_id),
        )
        if distance_ft is not None and distance_ft > aura_radius_ft:
            continue
        abilities = sheet.get("abilities") or {}
        cha_score = int(
            abilities.get("CHA")
            or abilities.get("cha")
            or 10,
        )
        cha_mod = max(1, (cha_score - 10) // 2)
        if cha_mod > best_bonus:
            best_bonus = cha_mod
            best_paladin = char
    return best_bonus, best_paladin


def _spell_installs_countercharmed_condition(spell_slug: str) -> bool:
    """v2.54.0 — gate for Bard Countercharm. Returns True when the
    spell's `_SPELL_CONDITION_MAP` entry installs a condition that
    Countercharm protects against (charmed or frightened). RAW:
    "advantage on saving throws against being frightened or charmed."

    Drives the condition-gated save-aura check — Countercharm only
    fires when the SPELL would install one of those conditions, not
    on every save. Today this means charm-person, fear, suggestion
    (added in this commit). Future content adds (Crown of Madness,
    Geas, Bestow Curse with charm option, Phantasmal Killer, etc.)
    pick up the gate automatically as their `_SPELL_CONDITION_MAP`
    entries land.
    """
    if not spell_slug:
        return False
    entry = _SPELL_CONDITION_MAP.get(spell_slug)
    if not entry:
        return False
    return (entry.get("key") or "").strip().lower() in {
        "charmed", "frightened",
    }


def _ally_has_countercharm_active(
    db: Session, campaign_id: int, saving_char_id: int | None,
) -> "tuple[bool, int | None]":
    """v2.54.0 — Bard Countercharm (Lv 6+) ally-aura gate. Returns
    (applies, bard_char_id). True when some PC combatant in the
    active battle's init tracker has a buff with key
    ``countercharm-active`` (installed by /use_countercharm), AND
    the saving PC is in the same battle. The bard's own aura
    protects themselves too (RAW: "you or any of your friendly
    creatures").

    v2.61.0 (F1) — adds a 30 ft radius gate. ``db: Session`` is now
    a required first arg so the helper can look up token positions
    via ``_distance_ft_between_chars``. When token positions are
    unavailable (no active map / no grid / either token off-map),
    falls back to the pre-v2.61.0 "any in init" behavior.

    v1 simplifications still apply:
      - The bard MUST keep using their action each turn to maintain
        Countercharm RAW; v1 installs a 1-round self-buff and lets
        it auto-expire. Re-cast each turn.
    """
    if not saving_char_id:
        return False, None
    state = hub.get_battle(campaign_id)
    if not state:
        return False, None
    combatants = state.get("combatants") or []
    saver_in_battle = any(
        c.get("char_id") == saving_char_id for c in combatants
    )
    if not saver_in_battle:
        return False, None
    for c in combatants:
        buffs = c.get("buffs") or []
        for b in buffs:
            if not isinstance(b, dict):
                continue
            if (b.get("key") or "").strip().lower() != "countercharm-active":
                continue
            bard_char_id = c.get("char_id")
            if not bard_char_id:
                continue
            # v2.61.0 — F1 range gate at 30 ft. RAW Countercharm
            # protects creatures "within 30 feet" — distinct from
            # AoP/AoD's 10 ft default. Same fall-back-to-no-position
            # semantics.
            distance_ft = _distance_ft_between_chars(
                db, campaign_id, int(bard_char_id), int(saving_char_id),
            )
            if distance_ft is not None and distance_ft > 30.0:
                continue
            return True, int(bard_char_id)
    return False, None


async def _broadcast_countercharm(
    campaign_id: int, bard: "Character", saving_char: "Character | None",
) -> None:
    """Companion broadcast for the Countercharm aura gate. Names the
    bard as the source ("Lyra's 🎺 Countercharm — advantage on save
    vs charm/fear for X").
    """
    if not bard:
        return
    target_name = saving_char.name if saving_char else "ally"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": bard.id,
            "character_name": bard.name,
            "user_color": bard.color,
            "feature_name": (
                f"🎺 Countercharm → advantage on {target_name}'s save"
            ),
            "feature_desc": (
                f"Allies within 30 ft of {bard.name} have advantage on "
                f"saves vs charmed / frightened."
            ),
            "source": "countercharm",
        },
    })


def _pc_has_purity_of_spirit(sheet: dict) -> bool:
    """v2.99.154 — Purity of Spirit (Paladin Oath of Devotion,
    Lv 15+, PHB p.87): "Beginning at 15th level, you are always
    under the effects of a protection from evil and good spell."

    Returns True when all three gates pass:
      1. Sheet's class (or any multiclass entry) is paladin
      2. Paladin level ≥ 15
      3. Subclass slug = "devotion" (normalized: strips "Oath of "
         prefix + lowercases)

    Used by the audit endpoint `/use_purity_of_spirit` for now;
    a future engine hook can read this helper and gate condition
    installs on charmed / frightened / possession FROM aberrations
    / celestials / elementals / fey / fiends / undead (RAW). The
    engine hook is filed since it needs creature-type metadata on
    the source.
    """
    if not sheet:
        return False
    paladin_lv = _paladin_level_from_sheet(sheet)
    if paladin_lv < 15:
        return False
    subclass_raw = (sheet.get("subclass") or "").strip().lower()
    subclass_slug = subclass_raw.replace("oath of ", "").strip()
    return subclass_slug == "devotion"


def _ally_has_aura_of_devotion(
    db: Session, campaign_id: int, saving_char_id: int | None,
) -> "tuple[bool, Character | None]":
    """v2.55.0 — Paladin Aura of Devotion (Oath of Devotion, Lv 7+).
    RAW (PHB p.86 — Devotion subclass): "your allies are immune to
    being charmed while within 10 feet of you. At 18th level, the
    range increases to 30 feet."

    Returns ``(applies, paladin_char)`` where ``applies`` is True
    when ANY Paladin Lv 7+ with subclass slug ``devotion`` is in
    the active battle's init tracker AND the saving PC is in
    battle too. The paladin's own aura applies to themselves
    (mirrors Aura of Protection's self-aura behavior).

    Distinct from Aura of Protection (v2.53.0) in two ways:
      1. **Subclass-gated** — only Oath of Devotion (not other
         paladin oaths). Subclass check normalizes the sheet's
         ``subclass`` field via slug-comparison (strips "Oath of "
         prefix, lowercases). Mirrors the convention used by
         `_FEATURE_ECONOMY` subclass tags ("devotion" / "ancients" /
         etc.).
      2. **Lv 7+ not Lv 6+** — Aura of Devotion unlocks at Paladin
         Lv 7; Aura of Protection at Lv 6. Caelan is the demo
         fixture for both (bumped Lv 5 → 6 in v2.53.0 then 6 → 7
         in v2.55.0).

    v1 simplification mirrors Aura of Protection: no 10 ft radius
    check (any qualifying paladin in init counts as in range).
    Filed for follow-up — same `_distance_ft_between_points`
    integration point.
    """
    if not saving_char_id:
        return False, None
    state = hub.get_battle(campaign_id)
    if not state:
        return False, None
    combatants = state.get("combatants") or []
    saver_in_battle = any(
        c.get("char_id") == saving_char_id for c in combatants
    )
    if not saver_in_battle:
        return False, None
    for c in combatants:
        char_id = c.get("char_id")
        if not char_id:
            continue
        char = db.query(Character).filter(Character.id == int(char_id)).first()
        if not char:
            continue
        sheet = char.sheet or {}
        paladin_lv = _paladin_level_from_sheet(sheet)
        if paladin_lv < 7:
            continue
        # v2.66.0 — F1 follow-up. Same conscious gate as AoP.
        if not _paladin_is_conscious(char):
            continue
        # Subclass check — normalize "Oath of Devotion" → "devotion"
        # so the gate matches the `_FEATURE_ECONOMY` subclass-tag
        # convention.
        subclass_raw = (sheet.get("subclass") or "").strip().lower()
        subclass_slug = subclass_raw.replace("oath of ", "").strip()
        if subclass_slug != "devotion":
            continue
        # v2.61.0 — F1 range gate. AoD radius 10 ft (Lv 7-17), 30 ft
        # (Lv 18+). Same fall-back-to-no-position semantics as AoP.
        aura_radius_ft = 30.0 if paladin_lv >= 18 else 10.0
        distance_ft = _distance_ft_between_chars(
            db, campaign_id, int(char_id), int(saving_char_id),
        )
        if distance_ft is not None and distance_ft > aura_radius_ft:
            continue
        return True, char
    return False, None


def _pc_has_rage_active_from_sheet(sheet: "dict | None") -> bool:
    """v2.99.202 — Sheet-only rage check (no hub access required).
    Reads `sheet["_buffs_active"]` (the v2.97.30+ Phase C.3 mirror
    of the active battle's combatant buffs) for a `rage` entry.
    Used by `_apply_hp_change`'s Relentless Rage hook, which
    receives only the Character row.

    Outside an active battle the rage buff is on the combatant but
    NOT mirrored; rage outside combat doesn't fire Relentless Rage
    naturally either (no damage being applied at 0 HP). v1
    acceptable simplification.
    """
    if not sheet:
        return False
    for b in (sheet.get("_buffs_active") or []):
        if not isinstance(b, dict):
            continue
        if (b.get("key") or "").strip().lower() == "rage":
            return True
    return False


def _pc_has_primal_champion(sheet: "dict | None") -> bool:
    """v2.99.205 — RAW Primal Champion (Barbarian Lv 20, PHB
    p.49): "At 20th level, you embody the power of the wilds.
    Your Strength and Constitution scores increase by 4. Your
    maximum for those scores is now 24."

    Returns True for Barbarian Lv 20+. The +4 STR/CON bonus is
    derived via `_primal_champion_stat_bonus`. Cap-to-24 is
    sheet-managed today (the sheet edit panel accepts arbitrary
    values; the +4 just shows up as an effective bonus when
    consumers ask for it).

    Phase F.1 final of the v2.99.193 phased completion plan.
    """
    if not sheet:
        return False
    return _barbarian_level_from_sheet(sheet) >= 20


def _primal_champion_stat_bonus(
    sheet: "dict | None", ability: str,
) -> int:
    """v2.99.205 — Return the Primal Champion stat bonus (+4 for
    STR / CON when PC is Barbarian Lv 20+; 0 otherwise). Consumed
    by `_apply_indomitable_might_floor` so the floor reflects the
    +4 bonus even when the sheet's `abilities.STR` shows the base
    value.
    """
    if not _pc_has_primal_champion(sheet):
        return 0
    ab = (ability or "").strip().upper()
    if ab in ("STR", "CON"):
        return 4
    return 0


def _pc_has_indomitable_might(sheet: "dict | None") -> bool:
    """v2.99.204 — RAW Indomitable Might (Barbarian Lv 18+, PHB
    p.49): "Beginning at 18th level, if your total for a Strength
    check is less than your Strength score, you can use that
    score in place of the total."

    Returns True when the PC is Barbarian Lv 18+. The
    construction-time floor is applied by
    `_apply_indomitable_might_floor` at /roll post-result, on
    STR-ability checks only (saves and attacks are excluded).

    Phase F.1 cont'd of the v2.99.193 phased completion plan.
    """
    if not sheet:
        return False
    return _barbarian_level_from_sheet(sheet) >= 18


def _apply_indomitable_might_floor(
    result: "object", sheet: "dict",
) -> "tuple[object, int | None, int | None]":
    """v2.99.204 — Floor the total of a STR check at the PC's STR
    score. Returns `(new_result, old_total, str_score)` — old/new
    are None when the floor didn't apply (total already >= STR
    score, or sheet lacks STR).

    Mutates the breakdown to suffix " (Indomitable Might floor)"
    and adjusts the total to the STR score when below.
    """
    str_score = int((sheet.get("abilities") or {}).get("STR") or 0)
    # v2.99.205 — Primal Champion (Barbarian Lv 20+) adds +4 to
    # STR. The Indomitable Might floor reflects the effective STR
    # so a Lv 20 Barbarian's floor is base_str + 4.
    str_score += _primal_champion_stat_bonus(sheet, "STR")
    if str_score <= 0:
        return result, None, None
    try:
        old_total = int(getattr(result, "total", 0) or 0)
    except (TypeError, ValueError):
        return result, None, None
    if old_total >= str_score:
        return result, None, None
    breakdown = getattr(result, "breakdown", "") or ""
    new_breakdown = (
        f"{breakdown} → {str_score} (Indomitable Might floor)"
    )
    try:
        import copy
        new_result = copy.copy(result)
        new_result.total = str_score
        new_result.breakdown = new_breakdown
    except Exception:
        return result, None, None
    return new_result, old_total, str_score


async def _broadcast_indomitable_might(
    campaign_id: int,
    char: "Character | None",
    old_total: int,
    str_score: int,
    stat_key: str,
) -> None:
    """v2.99.204 — Companion broadcast for the Indomitable Might
    floor. Emits a `feature_used(source="indomitable-might")` so
    the chat-card surfaces the trigger.
    """
    if not char:
        return
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": char.color,
            "feature_name": (
                f"💪 Indomitable Might — STR check {old_total} "
                f"→ {str_score}"
            ),
            "feature_desc": (
                f"{char.name} treated the STR check total "
                f"({old_total}) as their STR score ({str_score}) "
                f"for "
                f"{stat_key or 'a Strength check'} "
                f"(Barbarian Lv 18+ class feature)."
            ),
            "source": "indomitable-might",
            "stat_key": stat_key or "",
            "old_total": old_total,
            "new_total": str_score,
        },
    })


def _pc_has_persistent_rage(sheet: "dict | None") -> bool:
    """v2.99.203 — RAW Persistent Rage (Barbarian Lv 15+, PHB
    p.49): "Beginning at 15th level, your rage is so fierce that
    it ends early only if you fall unconscious or if you choose
    to end it."

    Returns True when the PC is Barbarian Lv 15+. The mechanical
    effect — skipping the RAW "rage ends if you don't attack a
    hostile creature OR don't take damage on your turn" early-end
    conditions — is forward-looking today: those early-end
    conditions aren't enforced in v1 (rage just ticks down
    `duration_rounds` per round). When the early-end checks land
    in a future commit, they'll consult this helper to skip the
    early-end branch for Lv 15+ Barbarians. Until then, the
    helper documents the feature + supports a descriptive sheet
    row.

    Falls unconscious / voluntary end still terminate rage today
    (both go through the existing `_remove_buff` path).

    Phase F.1 cont'd of the v2.99.193 phased completion plan.
    """
    if not sheet:
        return False
    return _barbarian_level_from_sheet(sheet) >= 15


def _pc_has_relentless_rage_available(sheet: "dict | None") -> bool:
    """v2.99.202 — Returns True when the PC is a Barbarian Lv 11+
    AND currently has an active rage buff mirrored on the sheet.
    Used by the `_apply_hp_change` Relentless Rage hook.
    """
    if not sheet:
        return False
    if _barbarian_level_from_sheet(sheet) < 11:
        return False
    return _pc_has_rage_active_from_sheet(sheet)


def _relentless_rage_current_dc(sheet: "dict | None") -> int:
    """v2.99.202 — Returns the current Relentless Rage CON save DC.
    RAW PHB p.49: starts at 10; +5 per use this rest. Resets on
    short or long rest. Stored on the sheet as
    `relentless_rage_dc` (defaults to 10 when absent).
    """
    if not sheet:
        return 10
    raw = sheet.get("relentless_rage_dc")
    try:
        dc = int(raw) if raw is not None else 10
    except (TypeError, ValueError):
        dc = 10
    return max(10, dc)


def _increment_relentless_rage_dc(sheet: dict) -> int:
    """v2.99.202 — In-place increment of the per-rest Relentless
    Rage DC (+5). Returns the new DC.
    """
    new_dc = _relentless_rage_current_dc(sheet) + 5
    sheet["relentless_rage_dc"] = new_dc
    return new_dc


def _maybe_relentless_rage_save(sheet: dict) -> "tuple[bool, int, int, int]":
    """v2.99.202 — Roll the Relentless Rage CON save. Returns
    `(passed, dc_used, save_total, con_mod)`. Mutates the sheet's
    `relentless_rage_dc` field +5 unconditionally (RAW: "each time
    you use this feature" — any attempt counts).
    """
    dc = _relentless_rage_current_dc(sheet)
    con = int((sheet.get("abilities") or {}).get("CON") or 10)
    con_mod = (con - 10) // 2
    try:
        r = dice_mod.roll(f"1d20+{con_mod}" if con_mod >= 0 else f"1d20{con_mod}")
        total = int(r.total or 0)
    except dice_mod.DiceParseError:
        total = 0
    passed = total >= dc
    _increment_relentless_rage_dc(sheet)
    return passed, dc, total, con_mod


def _pc_has_rage_active_buff(
    campaign_id: int, saving_char_id: int | None,
) -> bool:
    """v2.57.0 — Mindless Rage (Path of the Berserker, Lv 6+).
    Returns True if the saving PC has a rage buff active on their
    combatant. Used by the condition-install gate in
    ``/roll_request/{id}/respond`` to short-circuit the install of a
    Charmed or Frightened condition while raging.

    RAW: "Starting at 6th level, you can't be charmed or frightened
    while raging. If you are charmed or frightened when you enter
    your rage, the effect is suspended for the duration of the rage."
    v1 implements the install-block half (gate fires when an
    incoming save-fail would install Charmed/Frightened). The
    "suspend on enter rage" half is filed — needs ``/use_rage`` to
    walk existing buffs and mark suspended ones.

    Subclass check is intentionally NOT required at the gate site:
    the rage buff key is only installed by ``/use_rage`` for
    Barbarian-class PCs, and only Berserker bumps Mindless Rage at
    Lv 6. Future Path of the Totem Warrior / etc. won't share the
    "charmed/fright immunity" wording — when they ship, the gate
    grows a subclass check against the rager's sheet. Filed.
    """
    if not saving_char_id:
        return False
    state = hub.get_battle(campaign_id)
    if not state:
        return False
    for c in state.get("combatants") or []:
        if c.get("char_id") != saving_char_id:
            continue
        for b in (c.get("buffs") or []):
            if not isinstance(b, dict):
                continue
            if (b.get("key") or "").strip().lower() == "rage":
                return True
        return False
    return False


def _pc_has_rage_str_save_advantage(
    campaign_id: int, saving_char_id: "int | None", save_ability: str,
) -> bool:
    """v2.99.26 — Rage advantage on STR saves. RAW (PHB p.48): "you
    have advantage on Strength checks and Strength saving throws"
    while raging.

    Returns True only when (a) save_ability == "STR" and (b) the
    saving PC's combatant carries an active ``rage`` buff with
    ``str_save`` in its ``effects.advantage_on`` list.

    Wired into the 3 save-roll construction sites (`/cast_spell`
    single-target PC save, AoE PC save, `/place_aoe` PC server-rolled
    save). Caller swaps `1d20 → 2d20kh1` when this returns True;
    composes safely with other advantage sources via kh1-of-kh1.

    Distinct from `_pc_has_rage_active_buff` (v2.57.0 Mindless Rage —
    blocks charm/fright install when raging at Lv 6+) and
    `_attacker_has_str_attack_advantage` (v2.49.238 — STR attack
    advantage while raging). Closes the third RAW Rage benefit
    that was descriptive-only until now (the buff carries the
    ``str_save`` marker since v2.20.0 but no consumer ever read it).
    """
    if (save_ability or "").strip().upper() != "STR":
        return False
    if not saving_char_id:
        return False
    state = hub.get_battle(campaign_id)
    if not state:
        return False
    for c in state.get("combatants") or []:
        if c.get("char_id") != saving_char_id:
            continue
        for b in (c.get("buffs") or []):
            if not isinstance(b, dict):
                continue
            if (b.get("key") or "").strip().lower() != "rage":
                continue
            effects = b.get("effects")
            if not isinstance(effects, dict):
                continue
            adv = effects.get("advantage_on") or []
            if isinstance(adv, list) and "str_save" in adv:
                return True
        return False
    return False


