@router.post("/api/campaign/{campaign_id}/use_frenzy")
async def use_frenzy(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.226 — Phase E.8 of the v2.99.193 phased completion
    plan. Frenzy (Path of the Berserker Lv 3+, PHB p.49): "Starting
    when you choose this path at 3rd level, you can go into a
    frenzy when you rage. If you do so, for the duration of your
    rage you can make a single melee weapon attack as a bonus
    action on each of your turns after this one. When your rage
    ends, you suffer one level of exhaustion (which you can't
    remove until you finish a long rest)."

    Body: ``{character_id, override?}``.

    Validates Berserker Barbarian Lv 3+ + currently raging
    (rage buff on the combatant) + Phase 4 bonus chip. Marks the
    bonus slot + broadcasts. v1 announces only; the bonus-action
    melee attack itself is rolled via the normal `/attack` path.

    The "+1 exhaustion at rage-end" half is filed — would need a
    hook into `/end_buff` (or rage-buff teardown) to bump
    `sheet.exhaustion_level`. v1 GM-tracks manually.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Barbarian character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_berserker_path(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "berserker barbarian lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _barbarian_level_from_sheet(sheet),
        })

    # Frenzy RAW requires the barbarian to be raging — check the
    # active rage buff on the hub-state combatant.
    if not _pc_has_rage_active_buff(campaign_id, char.id):
        return JSONResponse(status_code=409, content={
            "error": "not_raging",
            "expected": "rage buff active on combatant",
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "frenzy",
            "label": "Frenzy",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "bonus")
    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": "💢 Frenzy — bonus melee attack",
            "feature_desc": (
                f"{char.name} frenzies — one melee weapon attack "
                f"as a bonus action this turn. "
                f"(Berserker Lv 3+ class feature; GM tracks the "
                f"+1 exhaustion at rage-end.)"
            ),
            "source": "frenzy",
            "over_budget": was_used,
            "over_budget_slot": "bonus" if was_used else "",
        },
    })

    return {
        "ok": True,
        "feature": "frenzy",
        "over_budget": was_used,
    }


@router.post("/api/campaign/{campaign_id}/use_intimidating_presence")
async def use_intimidating_presence(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.226 — Phase E.8 of the v2.99.193 phased completion
    plan. Intimidating Presence (Path of the Berserker Lv 10+,
    PHB p.49): "Beginning at 10th level, you can use your action
    to frighten someone with your menacing presence. When you do
    so, choose one creature that you can see within 30 feet of
    you. If the creature can see or hear you, it must succeed on
    a Wisdom saving throw (DC equal to 8 + your proficiency bonus
    + your Charisma modifier) or be frightened of you until the
    end of your next turn..."

    Body: ``{character_id, target_name?, override?}``.

    Validates Berserker Barbarian Lv 10+ + Phase 4 action chip.
    Computes DC = 8 + prof + CHA mod. Marks the action chip +
    broadcasts the DC for the GM to roll the target's Wis save
    manually. v1 ships as announce-only — the actual Frightened
    install on save-fail is the GM's call.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    target_name = (str(body.get("target_name") or "")).strip()[:80]
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Barbarian character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_berserker_path(sheet, 10):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "berserker barbarian lv 10+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _barbarian_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "intimidating-presence",
            "label": "Intimidating Presence",
            "strict": strict,
        })

    prof = int(sheet.get("proficiency_bonus") or 2)
    cha = int((sheet.get("abilities") or {}).get("CHA") or 10)
    cha_mod = (cha - 10) // 2
    dc = 8 + prof + cha_mod

    await _mark_battle_economy(campaign_id, char.id, "action")
    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    target_phrase = f" vs {target_name}" if target_name else ""
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"😨 Intimidating Presence — Wis DC {dc}"
                f"{target_phrase}"
            ),
            "feature_desc": (
                f"{char.name} menaces the target{target_phrase}. "
                f"Target makes a Wisdom save DC {dc} or be "
                f"Frightened until the end of {char.name}'s next "
                f"turn. (Berserker Lv 10+ class feature.)"
            ),
            "source": "intimidating-presence",
            "dc": dc,
            "target_name": target_name,
            "over_budget": was_used,
            "over_budget_slot": "action" if was_used else "",
        },
    })

    return {
        "ok": True,
        "feature": "intimidating-presence",
        "dc": dc,
        "target_name": target_name,
        "over_budget": was_used,
    }


@router.post("/api/campaign/{campaign_id}/use_tides_of_chaos")
async def use_tides_of_chaos(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.227 — Phase E.6 Phase 1 of the v2.99.193 phased
    completion plan. Tides of Chaos (Wild Magic Sorcerer Lv 1+,
    PHB p.103): "Starting at 1st level, you can manipulate the
    forces of chance and chaos to gain advantage on one attack
    roll, ability check, or saving throw. Once you do so, you
    must finish a long rest before you can use this feature
    again. Any time before you regain the use of this feature,
    the DM can have you roll on the Wild Magic Surge table
    immediately after you cast a sorcerer spell of 1st level or
    higher. You then regain the use of this feature."

    Body: ``{character_id}``.

    Validates Wild Magic Sorcerer Lv 1+ + `sheet.tides_of_chaos_uses
    >= 1`. Decrements the counter + installs a `tides-of-chaos-active`
    buff with `effects.next_roll_advantage: True` +
    `consume_on_d20_roll: True` (same shape as the v2.99.214 Hide in
    Plain Sight buff that the `/roll` consumer picks up). Broadcasts.

    See docs/plans/wild-magic.md for the Phase 2+ roadmap (Wild
    Magic Surge auto-roll, Bend Luck reaction, Controlled Chaos,
    Spell Bombardment).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Sorcerer character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_wild_magic(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "wild magic sorcerer lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _sorcerer_level_from_sheet(sheet),
        })

    uses = int(sheet.get("tides_of_chaos_uses") or 0)
    if uses <= 0:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Tides of Chaos",
        })

    sheet["tides_of_chaos_uses"] = uses - 1

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    tides_buff = {
        "key": "tides-of-chaos-active",
        "name": "Tides of Chaos — advantage on next roll",
        "icon": "🎲",
        "duration_rounds": 10,
        "duration_max": 10,
        "concentration": False,
        "source": "tides-of-chaos",
        "source_char_id": char.id,
        "effects": {
            "next_roll_advantage": True,
            "consume_on_d20_roll": True,
        },
        "desc": (
            "Tides of Chaos: advantage on the next attack roll, "
            "ability check, or saving throw. Consumed on the "
            "next d20 roll."
        ),
    }
    await _install_buff(campaign_id, char.id, tides_buff)
    _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": "🎲 Tides of Chaos — advantage on next roll",
            "feature_desc": (
                f"{char.name} bends the tides of chaos for "
                f"advantage on the next attack, check, or save. "
                f"Refills on a long rest. (Wild Magic Sorcerer "
                f"Lv 1+ class feature.)"
            ),
            "source": "tides-of-chaos",
            "uses_remaining": uses - 1,
        },
    })

    return {
        "ok": True,
        "feature": "tides-of-chaos",
        "uses_remaining": uses - 1,
        "buff_installed": True,
    }


@router.post("/api/campaign/{campaign_id}/use_bend_luck")
async def use_bend_luck(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.229 — Phase E.6 Phase 3 of the v2.99.193 phased
    completion plan. Bend Luck (Wild Magic Sorcerer Lv 6+, PHB
    p.103): "Starting at 6th level, you have the ability to
    twist fate using your wild magic. When another creature you
    can see makes an attack roll, an ability check, or a saving
    throw, you can use your reaction and spend 2 sorcery points
    to roll 1d4 and apply the number rolled as a bonus or penalty
    to the creature's roll. You can do so after the creature
    rolls but before any effects of the roll occur."

    Body: ``{character_id, mode, target_name?, override?}``.
    mode ∈ {bonus, penalty}.

    Validates Wild Magic Sorcerer Lv 6+ + sorcery_points >= 2 +
    Phase 4 reaction chip. Decrements 2 SP, rolls 1d4, marks
    reaction chip, broadcasts.

    v1 ships announce-only — the bonus/penalty is announced for
    the GM to apply to the target's just-rolled d20 manually
    (SimpleVTT doesn't yet pause-then-resume third-party rolls).
    See docs/plans/wild-magic.md Phase 3.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    mode = (str(body.get("mode") or "")).strip().lower()
    target_name = (str(body.get("target_name") or "")).strip()[:80]
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if mode not in ("bonus", "penalty"):
        raise HTTPException(400, "mode must be 'bonus' or 'penalty'")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Sorcerer character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_wild_magic(sheet, 6):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "wild magic sorcerer lv 6+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _sorcerer_level_from_sheet(sheet),
        })

    # Sorcery Points resource (need >= 2).
    resources = list(sheet.get("resources") or [])
    sp_row = None
    sp_idx = -1
    for i, r in enumerate(resources):
        if (r.get("key") or "").lower() == "sorcery-points":
            sp_row = dict(r)
            sp_idx = i
            break
    if sp_row is None:
        raise HTTPException(404, "No Sorcery Points resource on this sheet")
    sp_cur = int(sp_row.get("current") or 0)
    sp_max = int(sp_row.get("max") or 0)
    if sp_cur < 2:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Sorcery Points",
            "required": 2,
            "current": sp_cur,
        })

    # Phase 4 reaction-chip gate.
    was_used = _is_slot_used(campaign_id, char.id, "reaction")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "reaction",
            "char_name": char.name,
            "source": "bend-luck",
            "label": "Bend Luck",
            "strict": strict,
        })

    # Decrement 2 SP + roll 1d4.
    new_sp = sp_cur - 2
    sp_row["current"] = new_sp
    resources[sp_idx] = sp_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    try:
        d4 = dice_mod.roll("1d4").total
    except Exception:
        d4 = 1
    signed = d4 if mode == "bonus" else -d4

    await _mark_battle_economy(campaign_id, char.id, "reaction")
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "sorcery-points",
            "current": new_sp,
            "max": sp_max,
        },
    })

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    target_phrase = f" → {target_name}" if target_name else ""
    sign_label = "bonus" if mode == "bonus" else "penalty"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🎲 Bend Luck — 1d4 {sign_label} {signed:+}{target_phrase}"
            ),
            "feature_desc": (
                f"{char.name} bends luck: rolls 1d4 and applies "
                f"{signed:+} as a {sign_label} to the target's "
                f"just-rolled attack / check / save"
                f"{target_phrase}. Costs 2 sorcery points "
                f"(reaction). (Wild Magic Sorcerer Lv 6+ class "
                f"feature.)"
            ),
            "source": "bend-luck",
            "mode": mode,
            "d4": d4,
            "signed": signed,
            "target_name": target_name,
            "sp_remaining": new_sp,
            "over_budget": was_used,
            "over_budget_slot": "reaction" if was_used else "",
        },
    })

    return {
        "ok": True,
        "feature": "bend-luck",
        "mode": mode,
        "d4": d4,
        "signed": signed,
        "sp_remaining": new_sp,
        "over_budget": was_used,
    }


_SPELL_BOMBARDMENT_DIE_SIZES = {4, 6, 8, 10, 12}


def _is_spell_bombardment_used(
    campaign_id: int, attacker_char_id: int,
) -> bool:
    """v2.99.231 — Returns True if the PC has already used Spell
    Bombardment this turn. Tracked via
    ``combatant.economy.spell_bombardment_used`` on the hub-state
    combatant; reset client-side at turn-advance, same pattern as
    Colossus Slayer (v2.60.0)."""
    state = hub.get_battle(campaign_id)
    if not state:
        return False
    for c in state.get("combatants") or []:
        if c.get("char_id") == attacker_char_id:
            econ = c.get("economy") or {}
            return bool(isinstance(econ, dict) and econ.get("spell_bombardment_used"))
    return False


async def _mark_spell_bombardment_used(
    campaign_id: int, attacker_char_id: int,
) -> None:
    """v2.99.231 — Set the spell_bombardment_used flag. Mirror of
    `_mark_colossus_slayer_used`."""
    state = hub.get_battle(campaign_id)
    if not state:
        return
    target = None
    for c in state.get("combatants") or []:
        if c.get("char_id") == attacker_char_id:
            target = c
            break
    if target is None:
        return
    economy = target.get("economy") or {}
    if not isinstance(economy, dict):
        economy = {}
        target["economy"] = economy
    economy["spell_bombardment_used"] = True
    hub.set_battle(campaign_id, state)


@router.post("/api/campaign/{campaign_id}/use_spell_bombardment")
async def use_spell_bombardment(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.231 — Phase E.6 Phase 5 of the v2.99.193 phased
    completion plan. Spell Bombardment (Wild Magic Sorcerer Lv 18+,
    PHB p.103): "Beginning at 18th level, the harmful energy of
    your spells intensifies. When you roll damage for a spell and
    roll the highest number possible on any of the dice, choose
    one of those dice, roll it again and add that roll to the
    damage. You can use the feature only once per turn."

    Body: ``{character_id, die_size}`` where die_size in {4,6,8,10,12}.

    Validates Wild Magic Lv 18+ + once-per-turn flag (combatant
    economy `spell_bombardment_used`). Rolls 1d<die_size>, marks
    the flag, broadcasts.

    v1 ships announce-only — the player invokes this after seeing
    their damage roll show a max die. The bonus damage is announced
    via feature_used; the GM applies the bump to the existing
    damage roll manually.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    die_size = int(body.get("die_size") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if die_size not in _SPELL_BOMBARDMENT_DIE_SIZES:
        raise HTTPException(
            400,
            f"die_size must be one of {sorted(_SPELL_BOMBARDMENT_DIE_SIZES)}",
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Sorcerer character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_wild_magic(sheet, 18):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "wild magic sorcerer lv 18+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _sorcerer_level_from_sheet(sheet),
        })

    if _is_spell_bombardment_used(campaign_id, char.id):
        return JSONResponse(status_code=409, content={
            "error": "once_per_turn",
            "feature": "spell-bombardment",
        })

    try:
        extra = dice_mod.roll(f"1d{die_size}").total
    except Exception:
        extra = die_size

    await _mark_spell_bombardment_used(campaign_id, char.id)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"💥 Spell Bombardment — +{extra} damage (1d{die_size} reroll)"
            ),
            "feature_desc": (
                f"{char.name} rerolls one max-rolled d{die_size} "
                f"and adds {extra} to the damage of an evocation "
                f"spell this turn. (Wild Magic Sorcerer Lv 18+ "
                f"class feature; once per turn.)"
            ),
            "source": "spell-bombardment",
            "die_size": die_size,
            "extra_damage": extra,
        },
    })

    return {
        "ok": True,
        "feature": "spell-bombardment",
        "die_size": die_size,
        "extra_damage": extra,
    }


@router.post("/api/campaign/{campaign_id}/use_weapon_bond")
async def use_weapon_bond(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.232 — Phase E.2 Phase 1 of the v2.99.193 phased
    completion plan. Weapon Bond (Eldritch Knight Lv 3+, PHB
    p.74): "At 3rd level, you learn a ritual that creates a
    magical bond between yourself and one weapon... While the
    weapon is bonded to you, you can't be disarmed of that
    weapon unless you are incapacitated. If it is on the same
    plane of existence, you can summon that weapon as a bonus
    action on your turn, causing it to teleport instantly to
    your hand. You can have up to two bonded weapons, but can
    summon only one at a time with your bonus action."

    Body: ``{character_id, weapon_index, override?}``.

    Validates Eldritch Knight Lv 3+. Reads the weapon's slug or
    name from ``sheet.inventory[weapon_index]``, appends to
    ``sheet.bonded_weapons`` (list[str], max 2), persists,
    broadcasts. 409 ``cap_reached`` if already at 2 bonded
    weapons.

    v1 ships the bond persistence + announce. The "can't be
    disarmed" half is filed (no disarm action in SimpleVTT
    today); the bonus-action summon is filed (would need an
    "is the weapon equipped?" check on attack).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    weapon_index_raw = body.get("weapon_index")
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if weapon_index_raw is None:
        raise HTTPException(400, "weapon_index is required")
    try:
        weapon_index = int(weapon_index_raw)
    except (TypeError, ValueError):
        raise HTTPException(400, "weapon_index must be an integer")
    if weapon_index < 0:
        raise HTTPException(400, "weapon_index must be >= 0")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_eldritch_knight(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "eldritch knight fighter lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    inventory = list(sheet.get("inventory") or [])
    if weapon_index >= len(inventory):
        raise HTTPException(
            400,
            f"weapon_index {weapon_index} out of range "
            f"(inventory has {len(inventory)} items)",
        )
    item = inventory[weapon_index] or {}
    if (item.get("type") or "").lower() != "weapon":
        raise HTTPException(
            400,
            f"inventory[{weapon_index}] is not a weapon",
        )
    weapon_name = (item.get("name") or "").strip() or f"item-{weapon_index}"
    weapon_slug = (item.get("_slug") or weapon_name.lower().replace(" ", "-"))

    bonded = list(sheet.get("bonded_weapons") or [])
    if weapon_slug in bonded:
        # Idempotent re-bond — return current list.
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "character_name": char.name,
                "feature_name": f"🔗 Weapon Bond — {weapon_name} (already bonded)",
                "feature_desc": (
                    f"{char.name}'s bond with {weapon_name} is "
                    f"already active. No change."
                ),
                "source": "weapon-bond",
                "weapon_slug": weapon_slug,
                "weapon_name": weapon_name,
                "bonded_weapons": bonded,
                "already_bonded": True,
            },
        })
        return {
            "ok": True,
            "feature": "weapon-bond",
            "weapon_slug": weapon_slug,
            "bonded_weapons": bonded,
            "already_bonded": True,
        }
    if len(bonded) >= 2:
        return JSONResponse(status_code=409, content={
            "error": "cap_reached",
            "label": "Weapon Bond",
            "max": 2,
            "current": len(bonded),
        })

    bonded.append(weapon_slug)
    sheet["bonded_weapons"] = bonded

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🔗 Weapon Bond — {weapon_name}"
            ),
            "feature_desc": (
                f"{char.name} completes the hour-long ritual to "
                f"bond {weapon_name}. The weapon can be summoned "
                f"as a bonus action while on the same plane and "
                f"can't be disarmed unless incapacitated. "
                f"(Eldritch Knight Lv 3+ class feature.)"
            ),
            "source": "weapon-bond",
            "weapon_slug": weapon_slug,
            "weapon_name": weapon_name,
            "bonded_weapons": bonded,
            "already_bonded": False,
        },
    })

    return {
        "ok": True,
        "feature": "weapon-bond",
        "weapon_slug": weapon_slug,
        "bonded_weapons": bonded,
        "already_bonded": False,
    }


_SUPERIORITY_DIE_SIZES = {"d8", "d10", "d12"}


@router.post("/api/campaign/{campaign_id}/use_trip_attack")
async def use_trip_attack(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.233 — Phase E.1 Phase 1 of the v2.99.193 phased
    completion plan. Trip Attack maneuver (Battle Master Lv 3+,
    PHB p.74): "When you hit a creature with a weapon attack,
    you can expend one superiority die to attempt to knock the
    target down. You add the superiority die to the attack's
    damage roll, and if the target is Large or smaller, it must
    make a Strength saving throw. On a failed save, you knock
    the target prone."

    Body: ``{character_id, override?}``.

    Validates Battle Master Lv 3+ + ``sheet.resources`` has a
    `superiority-dice` entry with `current >= 1`. Decrements the
    counter, rolls 1d<size> (size from `sheet.superiority_die_size`,
    default d8), computes Maneuver DC = 8 + prof + max(STR_mod,
    DEX_mod), broadcasts.

    v1 ships announce-only — the +damage and STR save are
    announced for the GM to apply manually. /attack does not yet
    accept a `maneuver: "trip"` body field. See
    docs/plans/battle-master.md Phase 3.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_battle_master(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "battle master fighter lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    # Superiority-dice resource lookup.
    resources = list(sheet.get("resources") or [])
    sd_row = None
    sd_idx = -1
    for i, r in enumerate(resources):
        if (r.get("key") or "").lower() == "superiority-dice":
            sd_row = dict(r)
            sd_idx = i
            break
    if sd_row is None:
        raise HTTPException(
            404,
            "No Superiority Dice resource on this sheet",
        )
    sd_cur = int(sd_row.get("current") or 0)
    sd_max = int(sd_row.get("max") or 0)
    if sd_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Superiority Dice",
        })

    die_size = (sheet.get("superiority_die_size") or "d8").strip().lower()
    if die_size not in _SUPERIORITY_DIE_SIZES:
        die_size = "d8"

    new_sd = sd_cur - 1
    sd_row["current"] = new_sd
    resources[sd_idx] = sd_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    try:
        extra = dice_mod.roll(f"1{die_size}").total
    except Exception:
        extra = 1

    prof = int(sheet.get("proficiency_bonus") or 2)
    abilities = sheet.get("abilities") or {}
    str_mod = (int(abilities.get("STR") or 10) - 10) // 2
    dex_mod = (int(abilities.get("DEX") or 10) - 10) // 2
    save_dc = 8 + prof + max(str_mod, dex_mod)

    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "superiority-dice",
            "current": new_sd,
            "max": sd_max,
        },
    })

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🦵 Trip Attack — +{extra} damage (1{die_size}); "
                f"Str DC {save_dc} or Prone"
            ),
            "feature_desc": (
                f"{char.name} expends a superiority die: +{extra} "
                f"damage on the hit + the target (Large or smaller) "
                f"makes a Str save DC {save_dc} or fall Prone. "
                f"(Battle Master Lv 3+ maneuver; "
                f"{new_sd}/{sd_max} dice remaining.)"
            ),
            "source": "trip-attack",
            "extra_damage": extra,
            "die_size": die_size,
            "save_dc": save_dc,
            "dice_remaining": new_sd,
        },
    })

    return {
        "ok": True,
        "feature": "trip-attack",
        "extra_damage": extra,
        "die_size": die_size,
        "save_dc": save_dc,
        "dice_remaining": new_sd,
    }


@router.post("/api/campaign/{campaign_id}/use_warding_flare")
async def use_warding_flare(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.234 — Phase H.1 first ship of the v2.99.193 phased
    completion plan. Warding Flare (Light Domain Cleric Lv 1+,
    PHB p.60): "Also at 1st level, the light of your deity flares
    out to mete out divine punishment to attackers. When you are
    attacked by a creature within 30 feet of you that you can
    see, you can use your reaction to impose disadvantage on the
    attack roll, causing light to flare before the attacker
    before it hits or misses. An attacker that can't be blinded
    is immune to this feature. You can use this feature a number
    of times equal to your Wisdom modifier (a minimum of once).
    You regain all expended uses when you finish a long rest."

    Body: ``{character_id, attacker_name?, override?}``.

    Validates Light Domain Cleric Lv 1+ + ``sheet.resources`` has
    a `warding-flare` entry with `current >= 1` + Phase 4 reaction
    chip. Decrements the counter, marks the reaction chip,
    broadcasts. v1 ships announce-only — the disadvantage on the
    attacker's roll is announced for the GM to apply manually.

    The "attacker that can't be blinded is immune" half is filed
    (would need a condition-immunity lookup on the attacker's
    sheet / monster stat block).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    attacker_name = (str(body.get("attacker_name") or "")).strip()[:80]
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_light_domain(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "light domain cleric lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    # warding-flare resource lookup.
    resources = list(sheet.get("resources") or [])
    wf_row = None
    wf_idx = -1
    for i, r in enumerate(resources):
        if (r.get("key") or "").lower() == "warding-flare":
            wf_row = dict(r)
            wf_idx = i
            break
    if wf_row is None:
        raise HTTPException(
            404,
            "No Warding Flare resource on this sheet",
        )
    wf_cur = int(wf_row.get("current") or 0)
    wf_max = int(wf_row.get("max") or 0)
    if wf_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Warding Flare",
        })

    # Phase 4 reaction-chip gate.
    was_used = _is_slot_used(campaign_id, char.id, "reaction")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "reaction",
            "char_name": char.name,
            "source": "warding-flare",
            "label": "Warding Flare",
            "strict": strict,
        })

    wf_row["current"] = wf_cur - 1
    resources[wf_idx] = wf_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "reaction")
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "warding-flare",
            "current": wf_cur - 1,
            "max": wf_max,
        },
    })

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    attacker_phrase = f" against {attacker_name}" if attacker_name else ""
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"✨ Warding Flare — disadvantage{attacker_phrase}"
            ),
            "feature_desc": (
                f"{char.name} flares with divine light: the next "
                f"attack roll{attacker_phrase} is at disadvantage. "
                f"(Light Domain Cleric Lv 1+ class feature; "
                f"{wf_cur - 1}/{wf_max} uses remaining. Attackers "
                f"immune to being blinded are immune.)"
            ),
            "source": "warding-flare",
            "attacker_name": attacker_name,
            "uses_remaining": wf_cur - 1,
            "over_budget": was_used,
            "over_budget_slot": "reaction" if was_used else "",
        },
    })

    return {
        "ok": True,
        "feature": "warding-flare",
        "uses_remaining": wf_cur - 1,
        "over_budget": was_used,
    }


_WOTS_DAMAGE_TYPES = {"lightning", "thunder"}


@router.post("/api/campaign/{campaign_id}/use_wrath_of_the_storm")
async def use_wrath_of_the_storm(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.235 — Phase H.1 second domain of the v2.99.193
    phased completion plan. Wrath of the Storm (Tempest Domain
    Cleric Lv 1+, PHB p.62): "When a creature within 5 ft of you
    that you can see hits you with an attack, you can use your
    reaction to cause the creature to make a Dexterity saving
    throw. The creature takes 2d8 lightning or thunder damage
    (your choice) on a failed save, and half as much damage on a
    successful one. You can use this feature a number of times
    equal to your Wisdom modifier (a minimum of once). You regain
    all expended uses when you finish a long rest."

    Body: ``{character_id, damage_type, attacker_name?, override?}``
    where damage_type ∈ {lightning, thunder}.

    Validates Tempest Cleric Lv 1+ + ``sheet.resources`` has a
    `wrath-of-the-storm` entry with `current >= 1` + Phase 4
    reaction-chip gate. Decrements counter, marks chip, rolls
    2d8 server-side, computes spell save DC = 8 + prof + WIS mod,
    broadcasts. v1 ships announce-only — the GM applies the
    damage post-save manually.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    damage_type = (str(body.get("damage_type") or "")).strip().lower()
    attacker_name = (str(body.get("attacker_name") or "")).strip()[:80]
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if damage_type not in _WOTS_DAMAGE_TYPES:
        raise HTTPException(
            400,
            f"damage_type must be one of {sorted(_WOTS_DAMAGE_TYPES)}",
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_tempest_domain(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "tempest domain cleric lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    resources = list(sheet.get("resources") or [])
    w_row = None
    w_idx = -1
    for i, r in enumerate(resources):
        if (r.get("key") or "").lower() == "wrath-of-the-storm":
            w_row = dict(r)
            w_idx = i
            break
    if w_row is None:
        raise HTTPException(
            404,
            "No Wrath of the Storm resource on this sheet",
        )
    w_cur = int(w_row.get("current") or 0)
    w_max = int(w_row.get("max") or 0)
    if w_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Wrath of the Storm",
        })

    was_used = _is_slot_used(campaign_id, char.id, "reaction")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "reaction",
            "char_name": char.name,
            "source": "wrath-of-the-storm",
            "label": "Wrath of the Storm",
            "strict": strict,
        })

    w_row["current"] = w_cur - 1
    resources[w_idx] = w_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    try:
        damage = dice_mod.roll("2d8").total
    except Exception:
        damage = 9

    prof = int(sheet.get("proficiency_bonus") or 2)
    wis_mod = (int((sheet.get("abilities") or {}).get("WIS") or 10) - 10) // 2
    save_dc = 8 + prof + wis_mod

    await _mark_battle_economy(campaign_id, char.id, "reaction")
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "wrath-of-the-storm",
            "current": w_cur - 1,
            "max": w_max,
        },
    })

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    attacker_phrase = f" against {attacker_name}" if attacker_name else ""
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"⚡ Wrath of the Storm — Dex DC {save_dc} "
                f"or {damage} {damage_type}{attacker_phrase}"
            ),
            "feature_desc": (
                f"{char.name} channels divine wrath{attacker_phrase}: "
                f"target makes a Dex save DC {save_dc} or takes "
                f"{damage} {damage_type} damage (half on success). "
                f"(Tempest Domain Cleric Lv 1+ class feature; "
                f"{w_cur - 1}/{w_max} uses remaining.)"
            ),
            "source": "wrath-of-the-storm",
            "damage": damage,
            "damage_type": damage_type,
            "save_dc": save_dc,
            "attacker_name": attacker_name,
            "uses_remaining": w_cur - 1,
            "over_budget": was_used,
            "over_budget_slot": "reaction" if was_used else "",
        },
    })

    return {
        "ok": True,
        "feature": "wrath-of-the-storm",
        "damage": damage,
        "damage_type": damage_type,
        "save_dc": save_dc,
        "uses_remaining": w_cur - 1,
        "over_budget": was_used,
    }


