_FORGE_BLESSING_KINDS = {"weapon", "armor"}


@router.post("/api/campaign/{campaign_id}/use_blessing_of_the_forge")
async def use_blessing_of_the_forge(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.240 — Phase H.1 seventh non-Life Cleric domain of
    the v2.99.193 phased completion plan. Blessing of the Forge
    (Forge Domain Cleric Lv 1+, XGE p.18): "At 1st level, at the
    end of a long rest, you can touch one nonmagical object that
    is a suit of armor or a simple or martial weapon. Until the
    end of your next long rest or until you use this feature
    again, the object becomes a magic item, granting a +1 bonus
    to AC if it's armor or a +1 bonus to attack and damage rolls
    if it's a weapon."

    Body: ``{character_id, item_index}``.

    Validates Forge Cleric Lv 1+ + item_index in inventory range
    + item.type in {weapon, armor}. Persists
    `sheet.blessed_object = {item_index, slug, name, kind}`.
    Broadcasts. v1 records the blessing; appending the +1 to
    weapon attack_bonus / damage or to armor ac_value is filed
    for a follow-up commit (would touch the existing /attack
    and AC-derivation paths).

    "Until you use this feature again" is satisfied by single-
    field semantics — re-calling overwrites the prior blessing.
    "Until end of next long rest" is filed (would need a
    long-rest cleanup hook).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    item_index_raw = body.get("item_index")
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if item_index_raw is None:
        raise HTTPException(400, "item_index is required")
    try:
        item_index = int(item_index_raw)
    except (TypeError, ValueError):
        raise HTTPException(400, "item_index must be an integer")
    if item_index < 0:
        raise HTTPException(400, "item_index must be >= 0")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_forge_domain(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "forge domain cleric lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    inventory = list(sheet.get("inventory") or [])
    if item_index >= len(inventory):
        raise HTTPException(
            400,
            f"item_index {item_index} out of range "
            f"(inventory has {len(inventory)} items)",
        )
    item = inventory[item_index] or {}
    kind = (item.get("type") or "").lower()
    if kind not in _FORGE_BLESSING_KINDS:
        raise HTTPException(
            400,
            f"inventory[{item_index}] is type '{kind}'; "
            f"Blessing of the Forge accepts only "
            f"{sorted(_FORGE_BLESSING_KINDS)}",
        )
    name = (item.get("name") or "").strip() or f"item-{item_index}"
    slug = (item.get("_slug") or name.lower().replace(" ", "-"))

    sheet["blessed_object"] = {
        "item_index": item_index,
        "slug": slug,
        "name": name,
        "kind": kind,
    }

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    if kind == "weapon":
        bonus_desc = "+1 attack + damage rolls"
    else:
        bonus_desc = "+1 AC"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🔨 Blessing of the Forge — {name} ({bonus_desc})"
            ),
            "feature_desc": (
                f"{char.name} blesses {name} at the end of a long "
                f"rest: it becomes a magic item granting {bonus_desc} "
                f"until the next long rest or until this feature is "
                f"used again. (Forge Domain Cleric Lv 1+ class "
                f"feature.)"
            ),
            "source": "blessing-of-the-forge",
            "item_index": item_index,
            "slug": slug,
            "name": name,
            "kind": kind,
        },
    })

    return {
        "ok": True,
        "feature": "blessing-of-the-forge",
        "item_index": item_index,
        "slug": slug,
        "name": name,
        "kind": kind,
    }


@router.post("/api/campaign/{campaign_id}/use_eyes_of_the_grave")
async def use_eyes_of_the_grave(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.241 — Phase H.1 eighth non-Life Cleric domain of
    the v2.99.193 phased completion plan. Eyes of the Grave
    (Grave Domain Cleric Lv 1+, XGE p.19): "As an action, you
    can open your awareness to magically detect undead. Until
    the end of your next turn, you know the location of any
    undead within 60 feet of you that isn't behind total cover
    and that isn't protected from divination magic. This sense
    doesn't tell you anything about a creature's capabilities or
    identity. You can use this feature a number of times equal
    to your Wisdom modifier (a minimum of once). You regain all
    expended uses when you finish a long rest."

    Body: ``{character_id, override?}``.

    Validates Grave Cleric Lv 1+ + ``sheet.resources`` has an
    `eyes-of-the-grave` entry with `current >= 1` + Phase 4
    action chip. Decrements counter, marks chip, broadcasts.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_grave_domain(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "grave domain cleric lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    resources = list(sheet.get("resources") or [])
    e_row = None
    e_idx = -1
    for i, r in enumerate(resources):
        if (r.get("key") or "").lower() == "eyes-of-the-grave":
            e_row = dict(r)
            e_idx = i
            break
    if e_row is None:
        raise HTTPException(
            404,
            "No Eyes of the Grave resource on this sheet",
        )
    e_cur = int(e_row.get("current") or 0)
    e_max = int(e_row.get("max") or 0)
    if e_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Eyes of the Grave",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "eyes-of-the-grave",
            "label": "Eyes of the Grave",
            "strict": strict,
        })

    e_row["current"] = e_cur - 1
    resources[e_idx] = e_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "action")
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "eyes-of-the-grave",
            "current": e_cur - 1,
            "max": e_max,
        },
    })

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                "💀 Eyes of the Grave — detect undead 60 ft"
            ),
            "feature_desc": (
                f"{char.name} opens awareness to undead within "
                f"60 ft. Location-only sense (no capabilities / "
                f"identity); ignores creatures behind total cover "
                f"or anti-divination protection. Lasts until end "
                f"of next turn. (Grave Domain Cleric Lv 1+ class "
                f"feature; {e_cur - 1}/{e_max} uses remaining.)"
            ),
            "source": "eyes-of-the-grave",
            "uses_remaining": e_cur - 1,
            "over_budget": was_used,
            "over_budget_slot": "action" if was_used else "",
        },
    })

    return {
        "ok": True,
        "feature": "eyes-of-the-grave",
        "uses_remaining": e_cur - 1,
        "over_budget": was_used,
    }


@router.post("/api/campaign/{campaign_id}/use_vigilant_blessing")
async def use_vigilant_blessing(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.242 — Phase H.1 ninth non-Life Cleric domain of the
    v2.99.193 phased completion plan. Vigilant Blessing
    (Twilight Domain Cleric Lv 1+, TCE p.41): "As an action,
    you give one creature (including yourself) advantage on the
    next initiative roll the creature makes. This benefit ends
    immediately after the roll or if you use this feature again."

    Body: ``{character_id, target_combatant_id, override?}``.

    Validates Twilight Cleric Lv 1+ + target combatant exists in
    active battle + Phase 4 action chip. Installs `vigilant-
    blessing-active` buff on the target with
    `effects.init_advantage: True` (and a stealth_bonus proxy
    for the /roll consumer). Marks chip, broadcasts. No
    resource cost.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    target_combatant_id = (str(body.get("target_combatant_id") or "")).strip()
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if not target_combatant_id:
        raise HTTPException(400, "target_combatant_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_twilight_domain(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "twilight domain cleric lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    state = hub.get_battle(campaign_id) or {}
    target_char_id = None
    target_name = ""
    for c in (state.get("combatants") or []):
        if c.get("id") == target_combatant_id:
            target_char_id = c.get("char_id")
            target_name = c.get("name") or ""
            break
    if target_char_id is None:
        return JSONResponse(status_code=404, content={
            "error": "target_not_in_battle",
            "target_combatant_id": target_combatant_id,
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "vigilant-blessing",
            "label": "Vigilant Blessing",
            "strict": strict,
        })

    vb_buff = {
        "key": "vigilant-blessing-active",
        "name": "Vigilant Blessing — advantage on next init",
        "icon": "🌒",
        "duration_rounds": 100,
        "duration_max": 100,
        "concentration": False,
        "source": "vigilant-blessing",
        "source_char_id": char.id,
        "effects": {
            "init_advantage": True,
            "consume_on_initiative_roll": True,
        },
        "desc": (
            "Advantage on next initiative roll. Consumed on roll "
            "or replaced by next Vigilant Blessing."
        ),
    }
    await _install_buff(campaign_id, int(target_char_id), vb_buff)
    _mirror_buffs_to_sheet(
        db, int(target_char_id),
        _get_buffs(campaign_id, int(target_char_id)),
    )

    await _mark_battle_economy(campaign_id, char.id, "action")

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    is_self = int(target_char_id) == int(char.id)
    target_phrase = (
        "themselves" if is_self
        else (target_name or "an ally")
    )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🌒 Vigilant Blessing — {target_name or 'self'}"
            ),
            "feature_desc": (
                f"{char.name} grants {target_phrase} advantage on "
                f"the next initiative roll. (Twilight Domain "
                f"Cleric Lv 1+ class feature.)"
            ),
            "source": "vigilant-blessing",
            "target_combatant_id": target_combatant_id,
            "target_char_id": target_char_id,
            "target_name": target_name,
            "is_self": is_self,
            "over_budget": was_used,
            "over_budget_slot": "action" if was_used else "",
        },
    })

    return {
        "ok": True,
        "feature": "vigilant-blessing",
        "target_combatant_id": target_combatant_id,
        "target_char_id": target_char_id,
        "is_self": is_self,
        "buff_installed": True,
        "over_budget": was_used,
    }


@router.post("/api/campaign/{campaign_id}/use_emboldening_bond")
async def use_emboldening_bond(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.243 — Phase H.1 tenth non-Life Cleric domain of the
    v2.99.193 phased completion plan. Emboldening Bond (Peace
    Domain Cleric Lv 1+, TCE p.40): "You can use your action to
    forge an empowering bond among people who are at peace with
    one another... The total number of creatures who can be
    bonded by this feature at one time equals your proficiency
    bonus. While bonded creatures are within 30 feet of one
    another, they can each roll a d4 whenever they make an
    ability check, attack roll, or saving throw."

    Body: ``{character_id, target_combatant_ids: [...], override?}``.

    Validates Peace Cleric Lv 1+ + target list non-empty + count
    <= sheet.proficiency_bonus + each target exists in active
    battle + Phase 4 action chip. Installs `emboldening-bond-
    active` buff on each target with `effects.bonus_d4: True` +
    600-round duration (1 hour). Marks chip, broadcasts.

    The "while within 30 ft of one another" range check is filed
    (no automatic enforcement); RAW the 1-minute ritual to forge
    the bond is also dropped — v1 ships as a single action for
    in-play utility.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    target_ids = body.get("target_combatant_ids") or []
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if not isinstance(target_ids, list) or len(target_ids) < 1:
        raise HTTPException(
            400,
            "target_combatant_ids must be a non-empty list",
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_peace_domain(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "peace domain cleric lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    prof = int(sheet.get("proficiency_bonus") or 2)
    if len(target_ids) > prof:
        return JSONResponse(status_code=409, content={
            "error": "too_many_targets",
            "max": prof,
            "got": len(target_ids),
        })

    state = hub.get_battle(campaign_id) or {}
    cb_by_id = {
        c.get("id"): c for c in (state.get("combatants") or [])
    }
    bonded_char_ids: list[int] = []
    bonded_names: list[str] = []
    for tcid in target_ids:
        tcid = str(tcid).strip()
        cb = cb_by_id.get(tcid)
        if not cb or cb.get("char_id") is None:
            return JSONResponse(status_code=404, content={
                "error": "target_not_in_battle",
                "target_combatant_id": tcid,
            })
        bonded_char_ids.append(int(cb["char_id"]))
        bonded_names.append(cb.get("name") or "")

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "emboldening-bond",
            "label": "Emboldening Bond",
            "strict": strict,
        })

    eb_template = {
        "key": "emboldening-bond-active",
        "name": "Emboldening Bond — +1d4 to rolls",
        "icon": "🕊️",
        "duration_rounds": 600,
        "duration_max": 600,
        "concentration": False,
        "source": "emboldening-bond",
        "source_char_id": char.id,
        "effects": {
            "bonus_d4": True,
            "while_within_ft": 30,
        },
        "desc": (
            "While within 30 ft of another bonded creature, add "
            "1d4 to attack rolls, ability checks, and (via "
            "reaction) saving throws."
        ),
    }
    for tcid in bonded_char_ids:
        eb_buff = dict(eb_template)
        await _install_buff(campaign_id, tcid, eb_buff)
        _mirror_buffs_to_sheet(db, tcid, _get_buffs(campaign_id, tcid))

    await _mark_battle_economy(campaign_id, char.id, "action")

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    names_pretty = ", ".join(n for n in bonded_names if n) or "the bonded creatures"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🕊️ Emboldening Bond — {len(bonded_char_ids)} bonded"
            ),
            "feature_desc": (
                f"{char.name} forges an Emboldening Bond among "
                f"{names_pretty}. Within 30 ft of one another, "
                f"each can add 1d4 to one attack/check/save. "
                f"Lasts 1 hour or until recast. (Peace Domain "
                f"Cleric Lv 1+ class feature.)"
            ),
            "source": "emboldening-bond",
            "target_combatant_ids": [str(t) for t in target_ids],
            "bonded_char_ids": bonded_char_ids,
            "bonded_names": bonded_names,
            "over_budget": was_used,
            "over_budget_slot": "action" if was_used else "",
        },
    })

    return {
        "ok": True,
        "feature": "emboldening-bond",
        "bonded_char_ids": bonded_char_ids,
        "bonded_names": bonded_names,
        "max_allowed": prof,
        "buff_installed": True,
        "over_budget": was_used,
    }


@router.post("/api/campaign/{campaign_id}/select_hunters_prey")
async def select_hunters_prey(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.223 — Phase E.3 of the v2.99.193 phased completion
    plan. Hunter's Prey (Hunter Ranger Lv 3, PHB p.93): pick ONE
    of Colossus Slayer / Giant Killer / Horde Breaker.

    Body: ``{character_id, option}``. option ∈ {colossus-slayer,
    giant-killer, horde-breaker}.

    Validates Hunter Ranger Lv 3+. Persists
    `sheet.hunters_prey = <option>`. Colossus Slayer is already
    wired via `_compute_attack_auto_uplifts` (v2.60.0); Giant
    Killer + Horde Breaker get their own announce endpoints
    (`/use_giant_killer` + `/use_horde_breaker`).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    option = (str(body.get("option") or "")).strip().lower()
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if option not in _HUNTERS_PREY_OPTIONS:
        raise HTTPException(
            400,
            f"option must be one of {sorted(_HUNTERS_PREY_OPTIONS)}",
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    cls = (sheet.get("class") or "").lower()
    if cls != "ranger":
        return JSONResponse(status_code=409, content={
            "error": "wrong_class", "expected": "ranger",
            "got": cls or "",
        })
    if "hunter" not in (sheet.get("subclass") or "").strip().lower():
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass",
            "expected": "hunter",
            "got": (sheet.get("subclass") or "").strip().lower(),
        })
    if _ranger_level_from_sheet(sheet) < 3:
        return JSONResponse(status_code=409, content={
            "error": "level_too_low", "required": 3,
            "got": _ranger_level_from_sheet(sheet),
        })

    sheet["hunters_prey"] = option
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    pretty = option.replace("-", " ").title()
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": f"🏹 Hunter's Prey — {pretty}",
            "feature_desc": (
                f"{char.name} chose {pretty} as Hunter's Prey."
            ),
            "source": "hunters-prey-pick",
            "option": option,
        },
    })

    return {"ok": True, "option": option}


@router.post("/api/campaign/{campaign_id}/use_giant_killer")
async def use_giant_killer(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.223 — Giant Killer reaction announce. RAW PHB p.93:
    "When a Large or larger creature within 5 feet of you hits
    or misses you with an attack, you can use your reaction to
    attack that creature immediately after its attack."

    Body: ``{character_id, override?}``.

    Validates Hunter Ranger Lv 3+ with `hunters_prey ==
    "giant-killer"` + Phase 4 reaction slot gate. Marks the
    reaction chip + broadcasts feature_used. The actual attack
    is rolled normally via /attack.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    pick = _pc_hunters_prey_pick(sheet)
    if pick != "giant-killer":
        return JSONResponse(status_code=409, content={
            "error": "wrong_hunters_prey",
            "expected": "giant-killer",
            "got": pick,
        })

    was_used = _is_slot_used(campaign_id, char.id, "reaction")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "reaction",
            "char_name": char.name,
            "source": "giant-killer",
            "label": "Giant Killer",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "reaction")
    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": "🐘 Giant Killer — reaction attack",
            "feature_desc": (
                f"{char.name} used Giant Killer — reaction attack "
                f"on a Large+ creature within 5 ft. Roll the "
                f"attack normally."
            ),
            "source": "giant-killer",
            "over_budget": was_used,
            "over_budget_slot": "reaction" if was_used else "",
        },
    })

    return {"ok": True, "feature": "giant-killer",
            "over_budget": was_used}


