    # across many features, so a leaked mutation would surprise other
    # tests. Production sheet-edit flows use the dedicated subclass
    # cache keys (subclass_name + subclass_features) above, not these.
    "subclass",
    "fighting_style",
    "level",
    # v2.99.86 — class resources list (Mystic Arcanum L7/L8/L9,
    # Channel Divinity slots, Ki points, Bardic Inspiration, etc.).
    # Allowlisted for harness tests that need to inject or PATCH a
